if not Platform.isWindow() then
    return
end

---@class SharePreferences
local SharePreferences = T(Global, "SharePreferences")
SharePreferences.values = {}

local function getFileName()
    return string.format("game_cache/%s.cache", Game:getPlatformUserId())
end

function SharePreferences:init()
    os.execute("mkdir game_cache")
    local name = getFileName()
    local file = io.open(name, "r")
    if not file then
        return
    end
    local lines = StringUtil.split(file:read("*a"), "\n")
    file:close()
    for _, line in pairs(lines) do
        local key = StringUtil.split(line, "=")[1]
        local value = line:gsub(key .. "=", "")
        self.values[key] = value
    end
end

SharePreferences:init()

function SharePreferences:putStringForKey(key, value)
    self.values[key] = value
end

function SharePreferences:getStringForKey(key, default)
    return self.values[key] or default or ""
end

function SharePreferences:putBoolForKey(key, value)
    self.values[key] = tostring(value)
end

function SharePreferences:getBoolForKey(key, default)
    local value = self.values[key]
    if value == nil then
        return default == true
    end
    return value == "true"
end

function SharePreferences:close()
    local file = io.open(getFileName(), "w")
    local content = ""
    for key, value in pairs(self.values) do
        content = content .. key .. "=" .. value .. "\n"
    end
    file:write(content)
    file:close()
end

return SharePreferences--[[1jMxgxHtsBiNXS8B3Me9FFv2cIl2pjDmHdbHP]]---